-- Generated by scripts/generate-character-art-migration.ts from src/data/promotionalArt.ts.
--
-- Rewrites the art ledger from the shipped records. Every row is re-encoded to WebP at
-- display resolution, so a changed source changes its storage_path or asset_sha256; the
-- superseded rows point at files this release no longer serves and are removed rather than
-- disabled. The table holds catalog rows only, so this is safe to re-run.
begin;

-- Publisher-owned art mirrored by a community wiki, which grants nothing of its own.
alter table public.character_art_assets
  drop constraint character_art_reuse_mode,
  add constraint character_art_reuse_mode check (asset_reuse_mode in ('express-fan-kit', 'publisher-promotional', 'conditional-fan-kit', 'conditional-community-policy', 'written-permission', 'community-licensed', 'community-mirrored'));

delete from public.character_art_assets;

insert into public.character_art_assets (character_id, storage_path, source_url, source_publisher, license_url, asset_reuse_mode, credit_text, permission_evidence, asset_sha256, review_state, is_primary, retrieved_at, reviewed_at, disabled_at)
select c.id, '/art/2xko-ahri.webp', 'https://cmsassets.rgpub.io/sanity/images/dsfx7636/game_data_live/593043e42b15c4826f7e0fc2a0bea85a05cdd994-780x1040.png?accountingTag=2XKO', 'Riot Games', 'https://www.riotgames.com/en/legal', 'conditional-community-policy', 'MainStation was created under Riot Games'' "Legal Jibber Jabber" policy using assets owned by Riot Games. Riot Games does not endorse or sponsor this project.', 'Riot permits revocable non-commercial community use under its Legal Jibber Jabber policy. MainStation is a free community PWA with original profile and statistical content, and the required project notice is displayed; re-review is required if scope or monetization changes. Delivered as WebP re-encoded from the publisher source at display resolution; the source URL identifies the original asset.', 'sha256:356dd3d3beb5054cd77c50468a3a8a474f7df67752851755aaaaa6682718161e', 'approved', true, '2026-09-20', '2026-09-20', null
from public.characters c
join public.game_versions gv on gv.id = c.game_version_id
where gv.slug = '2xko' and c.slug = 'ahri' and c.roster_role = 'fighter'
on conflict (character_id, asset_sha256) do update set
  storage_path = excluded.storage_path, source_url = excluded.source_url, source_publisher = excluded.source_publisher,
